document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".watch-ad").forEach(e=>{e.addEventListener("click",function(){const t=this.dataset.adId,o=this.innerHTML;this.disabled=!0;let n=10;this.innerHTML=`Watching... (${n}s)`;const s=setInterval(()=>{n--,this.innerHTML=`Watching... (${n}s)`,n<=0&&(clearInterval(s),this.innerHTML="Claim Reward",(()=>{const n=new FormData;n.append("action","completeAd"),n.append("ad_id",t),fetch("../controllers/AdsController.php",{method:"POST",body:n}).then(e=>e.json()).then(t=>{this.innerHTML=o,this.disabled=!1,t.success?Toastify({text:t.message,duration:3e3,className:"info",style:{background:"linear-gradient(to right, #00b09b, #96c93d)"}}).showToast():Toastify({text:t.message||"An unknown error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()}).catch(t=>{console.error("Error:",t),this.innerHTML=o,this.disabled=!1,Toastify({text:"A network error occurred.",duration:3e3,className:"error",style:{background:"linear-gradient(to right, #ff5f6d, #ffc371)"}}).showToast()})})())},1e3)})})});
